    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            pivot = A[i][i]
            if pivot == 0:
                return None
            for j in range(n):
                A[i][j] /= pivot
            for j in range(m):
                if j != i and A[j][i] != 0:
                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] -= factor * A[i][k]
        return [row[:n-1] for row in A]

    def dpll(clauses, assignment, literals):
        if not clauses:
            return True
        literal = literals[0]
        positive_clauses = []
        negative_clauses = []
        for clause in clauses:
            if literal in clause:
                positive_clauses.append([l for l in clause if l != literal])
            elif -literal in clause:
                negative_clauses.append([l for l in clause if l != -literal])
        if dpll(positive_clauses, assignment + [literal], literals[1:]):
            return True
        if dpll(negative_clauses, assignment + [-literal], literals[1:]):
            return True
        return False

    def hodge_index(clause):
        n = len(clause)
        A = [[0] * (n+1) for _ in range(n)]
        for i in range(n):
            for j in range(i, n):
                if clause[i] == -clause[j]:
                    A[i][j] = 1
                    A[j][i] = 1
        rank = 0
        for row in gaussian_elimination(A):
            if any(row):
                rank += 1
        return rank

    def dpll_path_length(clauses, literals):
